(() => {
  if (window.__boploFlightLoaded) return;
  window.__boploFlightLoaded = true;
  const render = () => {
    const mount = document.querySelector('#marketing');
    if (!mount) return;
    document.title = 'Boplo Flight — Private-pilot training';
    mount.innerHTML = `<main class="flight-classic" id="top">
      <section class="fc-hero">
        <header class="fc-nav"><a href="#top" class="fc-brand" aria-label="Boplo Flight home"><img src="/assets/boplo-wordmark-blue-transparent.png" alt="Boplo"><span>FLIGHT</span></a><nav aria-label="Primary navigation"><a href="#inside">Features</a><a href="#route">Inside</a><a href="#route">The route</a><a href="#pricing">Pricing</a></nav><div class="fc-actions"><a href="#start">Sign in</a><a class="fc-start" href="#start">Start planning <b>↗</b></a></div></header>
        <div class="fc-hero-copy"><p class="fc-status"><i></i> Private pilot training, connected</p><h1>Your licence.<br><em>In one clear<br>picture.</em></h1><p>See the next lesson, theory, weather questions and flight record in one place — built around the licence you are working toward.</p><div class="fc-hero-links"><a class="fc-primary" href="#start">Build a flight plan <b>↗</b></a><a class="fc-secondary" href="#inside">See the control room</a></div></div>
        <div class="fc-sky" aria-hidden="true"><video autoplay muted loop playsinline preload="metadata"><source src="https://videos.pexels.com/video-files/13278451/13278451-uhd_3840_2160_30fps.mp4" type="video/mp4"></video><div class="fc-route-line r-one"></div><div class="fc-route-line r-two"></div></div>
        <aside class="fc-objective"><span>YOUR OBJECTIVE</span><strong>PPL(A)</strong><p>Private Pilot Licence</p></aside>
      </section>
      <section class="fc-intro" id="inside"><p>Everything a licence asks of you.</p><h2>One view for<br><em>the work ahead.</em></h2><div class="fc-control" aria-label="Boplo training control room"><header><span>YOUR TRAINING</span><b>PPL(A) · EXAMPLE WEEK</b><nav><button class="is-active" data-panel="prepare">Prepare</button><button data-panel="record">Record</button><button data-panel="brief">Brief</button></nav></header><div class="fc-control-body" data-control-body></div></div></section>
      <section class="fc-route" id="route"><p>The route is clear when the record is clear.</p><div><article><b>01</b><h3>Choose the licence.</h3><p>Build toward PPL(A), LAPL or your next rating with a date that belongs to you.</p></article><article><b>02</b><h3>See the next lesson.</h3><p>Keep the preparation, weather questions and theory that matter close together.</p></article><article><b>03</b><h3>Keep your record.</h3><p>Log the work you actually did. The useful context stays attached to it.</p></article></div></section>
      <section class="fc-loop" aria-labelledby="loop-title"><div class="fc-loop-intro"><p>THE TRAINING LOOP</p><h2 id="loop-title">What happens<br>between <em>lessons.</em></h2><p>Not another checklist. A focused loop that turns what happened last time into a better next session.</p></div><div class="fc-loop-stage"><div class="fc-loop-tabs" role="tablist" aria-label="Training loop"><button class="is-active" data-loop="1" role="tab" aria-selected="true"><b>01</b> After the lesson</button><button data-loop="2" role="tab" aria-selected="false"><b>02</b> Before the next</button><button data-loop="3" role="tab" aria-selected="false"><b>03</b> In the briefing</button></div><div class="fc-loop-screen" data-loop-screen></div></div></section>
      <section class="fc-boundary"><div class="fc-boundary-copy"><p>BUILT FOR THE REAL WORLD</p><h2>Clearer preparation.<br><em>Never false certainty.</em></h2><p>Boplo keeps your training visible. It does not clear you to fly, replace your instructor or substitute official weather and operational information.</p></div><div class="fc-boundary-rules"><article><b>01</b><h3>Your instructor stays in charge.</h3><p>Use Boplo to arrive better prepared, then make decisions with the person responsible for your training.</p></article><article><b>02</b><h3>Your record stays yours.</h3><p>Keep the notes, flight time and preparation history that explain how you got here.</p></article><article><b>03</b><h3>Official information stays official.</h3><p>Weather, NOTAMs and operating decisions should always be checked through the right source.</p></article></div></section>
      <section class="fc-pricing" id="pricing"><div class="fc-pricing-copy"><p>FLIGHT PLAN</p><h2>Start with your<br><em>actual training.</em></h2><p>Choose a licence, set a target and build from the next real lesson—not a generic course template.</p></div><div class="fc-price-detail"><span>ONE CLEAR PLAN</span><strong>£9.99</strong><p>Licence route, next-lesson preparation, theory prompts and your own record.</p><a class="fc-primary" href="#start">Build a flight plan <b>↗</b></a><small>For training support. Not flight instruction or operational approval.</small></div></section>
      <section class="fc-start-section" id="start"><p>YOUR FIRST OBJECTIVE</p><h2>Make the next<br>lesson count.</h2><button type="button" data-start>Start planning <b>↗</b></button></section>
      <footer class="fc-site-footer"><div class="fc-footer-brand"><img src="/assets/boplo-wordmark-blue-transparent.png" alt="Boplo"> FLIGHT</div><div><p>PRODUCT</p><a href="#inside">Training view</a><a href="#route">The route</a><a href="#pricing">Flight Plan</a></div><div><p>GUIDANCE</p><a href="#inside">For student pilots</a><a href="#start">Talk to us</a></div><div><p>LEGAL</p><a href="#start">Privacy</a><a href="#start">Terms</a></div><div class="fc-footer-note">Boplo supports preparation and record keeping. It is not flight instruction, operational approval, or a substitute for your instructor and official aviation information.</div></footer>
    </main>`;
    const panels={prepare:`<div class="fc-control-left"><span>UP NEXT</span><h3>Navigation<br>planning.</h3><p>One focused preparation block before Lesson 12.</p><button>Open preparation ↗</button></div><div class="fc-control-list"><p><b>MON 24</b> Air law review <i>Complete</i></p><p><b>WED 26</b> Route · diversion · radio <i>In progress</i></p><p><b>SAT 29</b> Lesson 12 · 10:30 <i>Booked</i></p></div>`,record:`<div class="fc-control-left"><span>YOUR RECORD</span><h3>Keep the<br>context.</h3><p>Log the work you did against the lesson it came from.</p><button>Open logbook ↗</button></div><div class="fc-control-list"><p><b>18 JUN</b> Circuits <i>Recorded</i></p><p><b>12 JUN</b> Stalling <i>Recorded</i></p><p><b>NEXT</b> Navigation <i>Ready to log</i></p></div>`,brief:`<div class="fc-control-left"><span>BEFORE THE LESSON</span><h3>Bring better<br>questions.</h3><p>Preparation prompts stay attached to the actual briefing.</p><button>Open brief ↗</button></div><div class="fc-control-list"><p><b>01</b> Confirm turning points <i>Route</i></p><p><b>02</b> Check official weather sources <i>Weather</i></p><p><b>03</b> Discuss diversion points <i>Decision</i></p></div>`};
    const body=mount.querySelector('[data-control-body]');const paint=key=>{body.innerHTML=panels[key];mount.querySelectorAll('[data-panel]').forEach(button=>button.classList.toggle('is-active',button.dataset.panel===key));};paint('prepare');mount.querySelectorAll('[data-panel]').forEach(button=>button.addEventListener('click',()=>paint(button.dataset.panel)));
    const loopPanels={
      1:`<div class="fc-loop-panel"><span>AFTER LESSON 11</span><h3>Turn the lesson<br>into a useful record.</h3><p class="fc-loop-note">“Need a cleaner diversion setup. Ask about the first frequency change before Lesson 12.”</p><div class="fc-loop-record"><div><b>TIME</b><span>1.1 hours logged</span><i>Added</i></div><div><b>NOTE</b><span>Navigation practice</span><i>Attached</i></div></div></div>`,
      2:`<div class="fc-loop-panel"><span>BEFORE LESSON 12</span><h3>Prepare the things<br>worth asking.</h3><p class="fc-loop-note">Boplo keeps the last lesson, your target and the work still open in the same view.</p><div class="fc-loop-record"><div><b>01</b><span>Review diversion timings</span><i><span class="fc-loop-mark done"></span></i></div><div><b>02</b><span>Check weather sources</span><i><span class="fc-loop-mark"></span></i></div><div><b>03</b><span>Build questions for brief</span><i><span class="fc-loop-mark"></span></i></div></div></div>`,
      3:`<div class="fc-loop-panel"><span>AT THE BRIEFING</span><h3>Make more of the<br>time with your instructor.</h3><p class="fc-loop-note">A short, relevant starting point—not a script and never a substitute for professional instruction.</p><div class="fc-loop-record"><div><b>ASK</b><span>When would you divert?</span><i>Route</i></div><div><b>ASK</b><span>What changes with today’s wind?</span><i>Weather</i></div></div></div>`
    };
    const loopScreen=mount.querySelector('[data-loop-screen]');
    const paintLoop=key=>{loopScreen.innerHTML=loopPanels[key];mount.querySelectorAll('[data-loop]').forEach(button=>{const selected=button.dataset.loop===key;button.classList.toggle('is-active',selected);button.setAttribute('aria-selected',String(selected));});};
    if(loopScreen){paintLoop('1');mount.querySelectorAll('[data-loop]').forEach(button=>button.addEventListener('click',()=>paintLoop(button.dataset.loop)));}
    mount.querySelector('[data-start]').addEventListener('click', () => {
      const notice = document.createElement('p'); notice.className = 'fc-notice'; notice.textContent = 'Flight-plan sign-up will open here.'; document.body.append(notice); requestAnimationFrame(() => notice.classList.add('show')); setTimeout(() => notice.remove(), 2600);
    });
    if (!matchMedia('(prefers-reduced-motion: reduce)').matches && window.gsap) {
      if (window.Lenis) { const lenis=new Lenis({lerp:.09,wheelMultiplier:.88}); const raf=time=>{lenis.raf(time);requestAnimationFrame(raf)};requestAnimationFrame(raf); }
      gsap.timeline({defaults:{ease:'power3.out'}}).from('.fc-nav',{y:-18,opacity:0,duration:.65}).from('.fc-hero-copy>*',{y:22,opacity:0,stagger:.08,duration:.58},'-=.24').from('.fc-sky video',{scale:1.04,opacity:0,duration:.9},'-=.48').from('.fc-objective',{y:16,opacity:0,duration:.45},'-=.42');
      if(window.ScrollTrigger){gsap.registerPlugin(ScrollTrigger);gsap.utils.toArray('.fc-intro,.fc-route,.fc-loop,.fc-boundary,.fc-pricing,.fc-start-section,.fc-site-footer').forEach(section=>{const targets=section.matches('.fc-loop,.fc-boundary,.fc-pricing')?section.children:section.querySelectorAll(':scope > p,:scope > h2,:scope > div,:scope > article,:scope > button');gsap.from(targets,{y:32,opacity:0,stagger:.1,duration:.78,ease:'power3.out',scrollTrigger:{trigger:section,start:'top 80%',once:true}});});gsap.to('.fc-sky video',{yPercent:8,ease:'none',scrollTrigger:{trigger:'.fc-hero',start:'top top',end:'bottom top',scrub:.45}});}
    }
  };
  document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', render, {once:true}) : render();
})();
